(window.TNQ=window.TNQ||[]).push({"terms":{"정상과학":{"d":"쿤이 말한 것으로, 지배적 패러다임 안에서 수행되는 일상적 과학 활동이다.","r":[]},"패러다임":{"d":"쿤이 제시한 개념으로, 한 시대 과학자 공동체가 공유하는 이론과 연구방식의 틀이다.","r":[]},"영가설":{"d":"변수 간 관계나 차이가 없다는 가설로, 연구가설에 대한 반증의 목적으로 설정된다.","r":[]},"연구가설":{"d":"변수 간에 관계가 있다는 연구자의 잠정적 진술로, 영가설을 기각하면 채택된다.","r":[]},"유의수준":{"d":"영가설을 기각할 때 허용하는 오류 확률의 기준이다. 검정 통계치의 확률이 이보다 낮으면 영가설을 기각한다.","r":[]},"외적타당도":{"d":"연구결과를 다른 대상과 상황으로 일반화할 수 있는 정도이다.","r":[]},"표집오차":{"d":"모수와 표본 통계치 사이에서 표본추출 과정에 생기는 차이로 표본이 클수록 작아진다.","r":[]},"신뢰수준":{"d":"추정한 구간이 모수를 포함할 확률의 수준으로, 높이려면 표본이 커져야 한다.","r":[]},"전수 연구":{"d":"모집단 전체를 조사 대상으로 삼는 연구입니다.","r":["표본 연구"]},"표본 연구":{"d":"모집단 일부를 뽑아 조사하고 그 결과로 전체를 추정하는 연구입니다.","r":["전수 연구"]},"확률표집":{"d":"모집단 각 요소가 뽑힐 확률을 알고 무작위로 표본을 추출하는 방법입니다.","r":["비확률표집"]},"비확률표집":{"d":"뽑힐 확률을 알 수 없게 연구자 판단이나 편의로 표본을 고르는 방법입니다.","r":["확률표집"]},"눈덩이표집":{"d":"조사 대상자의 소개를 받아 표본을 늘려가는 비확률표집으로 질적연구에서 쓴다.","r":[]},"의도적표집":{"d":"유의표집과 같은 뜻의 비확률표집이다.","r":[]},"신뢰도":{"d":"같은 대상을 반복 측정할 때 측정값이 일관된 정도이다.","r":[]},"타당도":{"d":"측정도구가 측정하려는 개념을 정확히 측정하는 정도이다.","r":[]},"요인분석법":{"d":"여러 문항을 공통 요인으로 묶어 개념의 구조를 확인하는 통계 방법으로, 타당도 검증에 쓴다.","r":[]},"내용분석":{"d":"문서, 방송, 기록 같은 기존 자료의 내용을 체계적으로 분석하는 비관여적 연구방법이다.","r":[]},"내러티브 탐구":{"d":"개인이 들려주는 이야기를 통해 경험의 의미를 해석하는 질적 연구방법입니다.","r":["내용분석"]},"양적조사":{"d":"수치로 자료를 수집해 통계적으로 분석하며 가설검증을 지향하는 조사로, 표본이 크고 일반화가 쉽다.","r":[]},"질적조사":{"d":"관찰과 면접으로 현상의 주관적 의미를 탐색하고 발견하는 조사로, 유연하게 진행되나 일반화가 어렵다.","r":[]},"귀납법":{"d":"개별 관찰 사례에서 출발해 일반적 원리를 이끌어내는 추론 방식이다.","r":[]},"연역법":{"d":"일반적 이론에서 가설을 도출해 경험적 자료로 검증하는 추론 방식이다.","r":[]},"패널조사":{"d":"동일한 대상을 일정한 시간 간격으로 반복 조사하는 종단조사의 한 유형이다.","r":[]},"경향조사":{"d":"같은 모집단에서 시점마다 다른 표본을 추출해 시간에 따른 변화를 보는 종단조사이다. 추세조사라고도 한다.","r":[]},"동년배 조사":{"d":"일정 기간에 같은 경험을 한 집단을 시점마다 추적해 조사하는 종단조사이다.","r":[]},"코호트":{"d":"출생이나 입학처럼 같은 시기에 같은 경험을 한 사람들의 집단이다.","r":[]},"횡단연구":{"d":"한 시점에서 여러 대상을 조사해 비교하는 연구이다.","r":[]},"종단연구":{"d":"둘 이상의 시점에서 조사해 시간에 따른 변화를 파악하는 연구이다.","r":[]},"논리적 실증주의":{"d":"경험으로 검증할 수 있는 지식만 의미가 있다고 보는 입장이다.","r":[]},"논리적 경험주의":{"d":"과학 이론은 관찰과 경험에 의한 검증으로 정당화된다고 보는 입장이다.","r":[]},"반증주의":{"d":"포퍼가 제시한 입장으로, 이론은 증명되는 것이 아니라 반증 가능성으로 평가된다고 본다.","r":[]},"후기실증주의":{"d":"객관적 지식을 추구하지만 직접적 확증은 불가능하다고 보며 이론의 잠정성을 인정하는 입장이다.","r":[]},"해석주의":{"d":"삶에 대한 심층적이고 주관적인 이해를 얻고자 하는 입장이다.","r":[]},"비판주의":{"d":"사회변화를 목적으로 사회의 구조적 측면에 주목하는 입장이다.","r":[]},"포스트모더니즘":{"d":"객관적 실재와 진리의 보편적 기준을 거부하는 입장이다.","r":[]},"분석단위":{"d":"연구에서 조사하고 분석하는 대상으로, 개인, 집단, 조직, 사회적 가공물 등이 있다.","r":[]},"사회적 가공물":{"d":"결혼식, 이혼, 교통사고, 요리책처럼 사람의 행위나 산물이 분석단위가 된 것이다.","r":[]},"생태학적 오류":{"d":"집단에 대한 분석 결과를 근거로 개인의 특성을 단정하는 오류이다.","r":[]},"기술적 연구":{"d":"현상의 빈도나 유형을 자세히 서술하는 연구이다.","r":[]},"설명적 연구":{"d":"현상이 발생한 원인과 이유를 밝히는 연구이다.","r":[]},"고지된 동의":{"d":"조사 목적과 위험, 혜택 등을 알린 뒤 참여자가 자발적으로 동의를 얻는 연구윤리 원칙이다.","r":[]},"독립변수":{"d":"다른 변수에 영향을 주는 원인 변수로 설명변수라고도 한다.","r":[]},"종속변수":{"d":"독립변수의 영향을 받아 변하는 결과 변수이다.","r":[]},"매개변수":{"d":"독립변수의 영향을 받아 종속변수에 영향을 미치는 중간 변수이다.","r":[]},"조절변수":{"d":"독립변수와 종속변수 관계의 강도나 방향에 영향을 미치는 변수이다.","r":[]},"통제변수":{"d":"독립변수와 종속변수의 관계에 영향을 줄 수 있어 그 영향을 일정하게 유지하는 변수이다.","r":[]},"선행변수":{"d":"독립변수보다 앞서 독립변수에 영향을 주는 변수이다.","r":[]},"내적타당도":{"d":"종속변수의 변화가 독립변수 때문이라고 확신할 수 있는 정도이다.","r":[]},"통계적 회귀":{"d":"극단적인 값이 재측정에서 평균 쪽으로 돌아오려는 경향으로 내적타당도를 해친다.","r":[]},"솔로몬 4집단 설계":{"d":"통제집단 사전사후검사 설계와 통제집단 사후검사 설계를 결합해 사전검사 효과를 통제하는 실험설계이다.","r":[]},"통제집단 사후검사 설계":{"d":"사전검사 없이 실험집단과 통제집단을 무작위로 배정하고 사후검사만 하는 설계이다.","r":[]},"정태적 집단 비교설계":{"d":"무작위 배정 없이 이미 존재하는 두 집단에 사후검사만 해 비교하는 전실험설계이다.","r":[]},"단일집단 사전사후검사 설계":{"d":"한 집단에 사전검사, 개입, 사후검사를 하는 전실험설계로, 통제집단이 없다.","r":[]},"시계열 설계":{"d":"한 집단을 개입 전후로 여러 차례 반복 측정하는 유사실험설계이다.","r":[]},"유사(준)실험설계":{"d":"무작위 배정이 어려울 때 사용하며, 순수실험설계보다 인과 추론 정도가 낮다.","r":[]},"전실험설계":{"d":"무작위 배정이나 통제가 부족해 내적타당도가 낮은 설계이다.","r":[]},"단일사례설계":{"d":"한 사례의 개입 전 기초선과 개입 후를 비교해 효과를 평가하는 설계이다.","r":[]},"기초선":{"d":"단일사례설계에서 개입 이전의 표적행동 상태를 반복 측정한 단계(A)이다.","r":[]},"복수기초선설계":{"d":"AB설계를 여러 대상, 상황, 문제에 적용해 동일한 효과가 나타나는지 확인하는 설계이다.","r":[]},"ABAB설계":{"d":"기초선, 개입, 철회, 재개입을 반복해 개입 효과와 외부사건의 영향을 확인하는 단일사례설계이다.","r":[]},"경향선":{"d":"단일사례설계에서 측정값의 변화 방향을 나타내는 선이다.","r":[]},"평균비교":{"d":"기초선과 개입기의 평균을 비교하는 분석으로 기초선이 안정적일 때 적합하다.","r":[]},"비관여적 관찰":{"d":"연구 대상이 관찰되는 줄 모르게 하는 관찰로 반응성을 줄인다.","r":[]},"명목척도":{"d":"성별과 혈액형처럼 서열 없이 범주로만 구분하는 척도이다.","r":[]},"서열척도":{"d":"순서 정보는 있으나 간격이 같지 않은 척도이다.","r":[]},"등간척도":{"d":"간격이 같으나 절대 0점이 없는 척도로 온도와 지능지수가 있다.","r":[]},"비율척도":{"d":"절대 0점이 있어 비율 계산이 가능한 척도이다.","r":[]},"리커트척도":{"d":"문항별 응답 점수를 합산해 태도를 측정하며 문항 간 내적 일관성이 중요하다.","r":[]},"거트만척도":{"d":"강도가 점차 높아지는 문항으로 구성된 누적척도이다.","r":[]},"서스톤척도":{"d":"평가자들이 문항에 가중치를 매겨 개발하는 척도로 개발이 번거롭다.","r":[]},"보가더스척도":{"d":"사회집단 간의 심리적 거리감을 측정하는 누적척도이다. 사회적 거리척도라고도 한다.","r":[]},"의미분화척도":{"d":"한 쌍의 상반된 형용사를 양 끝에 두어 느낌이나 감정을 측정하는 척도이다.","r":[]},"의미차별":{"d":"한 쌍의 상반된 형용사로 대상에 대한 느낌과 감정을 측정하는 척도이다.","r":[]},"재검사법":{"d":"같은 대상에게 같은 도구를 시간 간격을 두고 다시 측정해 신뢰도를 보는 방법이다.","r":[]},"반분법":{"d":"측정도구를 반으로 나누어 두 점수를 비교해 신뢰도를 보는 방법이다.","r":[]},"대안법":{"d":"동등한 두 도구를 같은 대상에게 적용해 신뢰도를 보는 방법이다.","r":[]},"내적일관성":{"d":"하나의 개념을 측정하는 문항들이 서로 일관되는 정도이다.","r":[]},"알파계수":{"d":"문항 간 내적 일관성으로 신뢰도를 측정하는 계수이다.","r":[]},"내용타당도":{"d":"측정도구가 개념의 의미를 빠짐없이 포괄하는 정도로 전문가 판단으로 확인한다.","r":[]},"동시타당도":{"d":"새 도구의 측정값을 이미 타당성이 입증된 기존 도구의 측정값과 비교해 보는 기준타당도이다.","r":[]},"판별타당도":{"d":"이론적으로 관련이 없는 개념을 측정한 척도들 사이의 상관이 낮은 정도이다.","r":[]},"요인분석":{"d":"여러 문항을 공통 요인으로 묶어 개념의 구성을 살피는 통계 방법으로, 구성타당도 확인에 쓴다.","r":[]},"조작적 정의":{"d":"개념을 실제로 관찰하고 측정할 수 있는 수준으로 구체화한 정의이다. 개념적 정의와 측정 사이의 과정이다.","r":[]},"개념적 정의":{"d":"개념의 의미를 다른 개념으로 풀어 설명한 이론적 정의이다.","r":[]},"체계적 오류":{"d":"측정값이 일정한 방향으로 치우치는 오류로 타당도를 낮춘다.","r":[]},"무작위 오류":{"d":"우연에 의해 측정값이 일정하지 않게 변하는 오류로 신뢰도를 낮춘다.","r":[]},"측정의 다각화":{"d":"여러 방법으로 측정해 오류를 줄이고 객관성을 높이는 것이다.","r":[]},"누적척도":{"d":"문항이 강도 순으로 배열되어 어느 문항에 동의하면 앞 문항에도 동의하는 것으로 간주하는 척도이다. 보가더스척도와 거트만척도가 해당한다.","r":[]},"구성타당도":{"d":"척도가 측정하려는 개념과 연관된 이론적 합의 및 개념 구조와 일치하는 정도이다.","r":[]},"표본오차":{"d":"모집단의 모수와 표본의 통계치 간 차이로, 표본크기가 클수록 줄어든다.","r":[]},"표준오차":{"d":"표본 통계치가 모수 주위에서 흩어지는 정도를 나타내며 표집오차의 크기를 가늠하게 한다.","r":[]},"모집단":{"d":"연구자가 결과를 일반화하려는 전체 대상이다.","r":[]},"모수":{"d":"모집단의 특성을 나타내는 수치이다.","r":[]},"통계치":{"d":"표본에서 계산한 특성값으로 모수를 추정하는 데 쓴다.","r":[]},"표집틀":{"d":"표본을 뽑기 위해 모집단의 구성원을 목록으로 만든 것이다.","r":[]},"표집간격":{"d":"체계적 표집에서 표본을 뽑는 일정한 번호 간격이다.","r":[]},"전수조사":{"d":"모집단 전체를 조사하는 방법으로 모수와 통계치의 구분이 필요하지 않다.","r":[]},"비표본오차":{"d":"측정 오류나 응답 거부처럼 표본추출 이외의 과정에서 생기는 오차이다.","r":[]},"단순무작위표집":{"d":"모집단의 모든 구성원이 같은 확률로 뽑히도록 무작위로 추출하는 확률표집이다.","r":[]},"층화표집":{"d":"모집단을 주요 특성별 층으로 나눈 뒤 각 층에서 무작위로 추출해 표집오차를 줄이는 확률표집이다.","r":[]},"체계적표집":{"d":"첫 표본을 무작위로 정하고 일정한 표집간격으로 선정하는 확률표집으로, 주기성이 문제될 수 있다.","r":[]},"집락표집":{"d":"모집단을 집단 단위로 나누어 집단을 무작위로 뽑고 그 구성원을 조사하는 확률표집이다. 표집틀이 없을 때 쓴다.","r":[]},"군집표집":{"d":"집락표집과 같은 뜻으로, 집단 단위로 표본을 추출한다.","r":[]},"할당표집":{"d":"모집단의 주요 특성 비율에 맞게 표본 수를 할당한 뒤 임의로 선정하는 비확률표집이다.","r":[]},"유의표집":{"d":"연구자의 판단으로 연구 목적에 맞는 대상을 의도적으로 선정하는 비확률표집이다.","r":[]},"우발적표집":{"d":"우연히 만난 대상이나 접근하기 쉬운 대상을 표본으로 삼는 비확률표집이다.","r":[]},"극단적 사례":{"d":"매우 드물거나 특이한 사례를 골라 조사하는 질적연구의 표집방법이다.","r":[]},"결정적 사례":{"d":"이론이나 현상의 이해에 핵심이 되는 사례를 골라 조사하는 질적연구의 표집방법이다.","r":[]},"비관여적":{"d":"연구 대상에게 영향을 주지 않고 자료를 얻는 방식이다.","r":[]},"개방형 질문":{"d":"응답범주를 제시하지 않고 응답자가 자유롭게 대답하게 하는 질문이다.","r":[]},"행렬식":{"d":"여러 문항이 같은 응답범주를 공유하도록 표 형태로 묶어 배열한 질문 방식이다.","r":[]},"이중질문":{"d":"한 문항에 두 가지 내용을 함께 묻는 질문으로 피해야 한다.","r":[]},"유도질문":{"d":"특정 응답을 하도록 이끄는 질문으로 피해야 한다.","r":[]},"프로빙":{"d":"면접에서 응답을 더 깊이 이끌어내려고 추가로 묻는 기술이다.","r":[]},"우편조사":{"d":"설문지를 우편으로 보내 응답받는 조사로 익명성이 높으나 응답률이 낮다.","r":[]},"배포조사":{"d":"설문지를 나누어주고 응답하게 해 거두는 조사이다.","r":[]},"비참여관찰":{"d":"관찰자가 관찰 대상과 상호작용하지 않고 지켜보며 자료를 얻는 방법이다.","r":[]},"반구조화된 면접":{"d":"질문 지침을 두되 순서와 표현을 유연하게 조정하는 면접이다.","r":[]},"비구조화 면접":{"d":"미리 정한 질문 없이 자유롭게 진행하는 표준화 정도가 낮은 면접이다.","r":[]},"심층면접":{"d":"주제에 관해 응답자와 깊이 있게 이야기하며 자료를 얻는 표준화 정도가 낮은 면접이다.","r":[]},"스케줄-구조화 면접":{"d":"질문 문항과 순서를 미리 정해 놓고 동일하게 진행하는 표준화된 면접이다.","r":[]},"근거이론":{"d":"수집된 자료에서 개방코딩, 축코딩, 선택코딩을 거쳐 이론을 생성하는 질적 연구방법이다.","r":[]},"개방코딩":{"d":"근거이론의 첫 단계로 자료를 개념으로 쪼개고 범주화하는 과정이다.","r":[]},"축코딩":{"d":"범주 간 관계를 인과적 조건, 맥락, 중재조건, 전략, 결과로 연결하는 과정이다.","r":[]},"선택코딩":{"d":"핵심범주를 중심으로 다른 범주를 통합하고 정교화해 이론을 만드는 과정이다.","r":[]},"삼각측정":{"d":"여러 방법, 자료, 연구자를 활용해 결과를 교차 확인하는 질적조사의 엄격성 확보 방법이다.","r":[]},"부정적 사례":{"d":"연구자가 발견한 패턴에 맞지 않는 사례로, 이를 분석하면 질적조사의 엄격성이 높아진다.","r":[]},"문화기술지":{"d":"특정 집단이 공유하는 생활양식의 의미를 이해하기 위한 질적 연구방법이다. 민속학적 연구라고도 한다.","r":[]},"내러티브":{"d":"개인의 경험 이야기를 수집해 의미를 해석하는 질적 연구방식이다.","r":[]},"참여행동":{"d":"연구 참여자가 연구 과정에 주체로 참여해 사회변화를 추구하는 연구방법이다.","r":[]},"라포르":{"d":"연구자와 연구 참여자 사이에 형성되는 신뢰관계이다.","r":[]},"초점집단":{"d":"소수 참여자가 주제에 관해 집단으로 토론하게 해 자료를 얻는 조사방법이다.","r":[]},"델파이기법":{"d":"익명의 전문가 패널에게 반복해서 의견을 묻고 합의를 도출하는 방법이다.","r":[]},"후광효과":{"d":"한 가지 두드러진 특성이 다른 평가에 영향을 미치는 현상이다.","r":[]},"제1종 오류":{"d":"참인 영가설을 기각하는 오류로, 신뢰수준을 높이면 줄어든다.","r":[]},"제2종 오류":{"d":"거짓인 영가설을 채택하는 오류이다.","r":[]},"1종 오류":{"d":"참인 영가설을 잘못 기각하는 오류로, 신뢰수준을 높이면 줄어든다.","r":[]},"통계적 검증력":{"d":"영가설이 거짓일 때 이를 기각할 수 있는 확률이다.","r":[]},"유의확률":{"d":"영가설이 참이라고 가정할 때 관찰된 결과 이상이 나올 확률로, 유의수준보다 낮으면 영가설을 기각한다.","r":[]},"대립가설":{"d":"영가설이 기각될 때 채택되는 가설로 연구가설과 같다.","r":[]},"산술평균":{"d":"측정값의 합을 사례 수로 나눈 값으로 등간척도 이상의 변수에 적합하다.","r":[]},"선정편향":{"d":"연구 대상이나 자료가 체계적으로 치우치게 선택되어 결과가 왜곡되는 현상이다.","r":[]}},"notes":{"개념적 정의를 실제 관찰 가능한 속성으로 전환시키는 과정이다":"머릿속 개념을 눈으로 확인하고 잴 수 있는 구체적 속성으로 바꾸는 일입니다.","검사(testing) 효과를 통제하기 어렵다":"같은 검사를 여러 번 받으면 익숙해져 점수가 달라지는데 통제집단이 없어 이를 가려내기 어렵습니다.","검사-재검사 방법은 신뢰도를 측정하는 방법이다":"같은 사람에게 시간을 두고 두 번 검사해 점수가 비슷한지 봄으로써 일관성을 판단합니다.","경험적으로 검증이 가능하여야 한다":"가설은 관찰이나 측정 자료로 맞는지 가려낼 수 있어야 연구에 쓸 수 있습니다.","고정반응이 나타나도록 배열한다":"고정반응은 내용과 상관없이 같은 번호만 고르는 응답 습관이라 질문지는 이를 피하도록 배열합니다.","과학적 혁명에서 패러다임 전환을 제시하였다":"쿤은 과학이 조금씩 쌓이기보다 지배적 틀이 통째로 바뀌는 혁명으로 발전한다고 보았습니다.","관찰과 면접을 통해 자료수집을 한다":"질적연구는 현장을 보거나 사람과 대화하는 방식으로 자료를 모읍니다.","관찰대상의 승인을 받지 않고 관찰한다는 점에서 연구윤리문제가 제기될 수 있다":"대상이 모르게 관찰하면 사전 동의를 받지 않은 것이라 윤리 문제가 생깁니다.","관찰로부터 이론을 도출하는 귀납적 방법을 활용한다":"개별 관찰에서 출발해 일반적인 이론으로 나아가므로 귀납적 접근입니다.","군집표집에 의한 조사에 비해 표집오차를 줄일 수 있다":"집단 단위로 뽑는 군집표집보다 개별 요소를 직접 뽑는 방법이 대체로 오차가 작습니다.","그 속성에 따라 직선이 아닌 곡선의 형태로도 나타날 수 있다":"변수 사이의 관계는 늘 직선이 아니고 변수의 성질에 따라 곡선을 그리기도 합니다.","기초선을 설정할 시간적 여유가 없이 개입해야 하는 사례에 적합하다":"위기 상황처럼 개입 전 상태를 관찰할 시간이 없는 사례에서 기초선 없이 쓸 수 있습니다.","내러티브 탐구에 비해 보다 많은 사례를 분석할 수 있다":"내용분석은 기록 자료를 대량으로 다룰 수 있어 한 사람의 이야기를 깊이 보는 방법보다 사례 수가 많습니다.","내용분석에 비해 과정중심적으로 접근할 수 있다":"내러티브 탐구는 이야기가 전개되는 흐름을 따라가므로 경험의 과정을 살피는 데 유리합니다.","눈덩이표집(snowball sampling)은 질적연구나 · 현장연구에서 많이 사용된다":"찾기 어려운 대상을 소개받아 늘려 가는 방식이라 질적 현장연구에 자주 씁니다.","다른 조건이 동일하다면, 동일 개념에 대한 측정도구의 문항 수가 많아질수록 신뢰도는 높아지는 경향이 있다":"같은 개념을 묻는 문항이 늘면 우연한 응답 오류가 서로 상쇄되어 일관성이 높아집니다.","독립변수가 2개 이상일 때 적용하는 설계이다":"독립변수가 둘 이상이면 각 변수의 효과와 변수들이 함께 만드는 효과를 요인 설계로 봅니다.","독립변수와 종속변수 간의 관계의 강도에 영향을 미칠 수 있다":"조절변수는 독립변수의 효과가 크게 또는 작게 나타나도록 조건 구실을 합니다.","독립변수와 종속변수의 관계에 영향을 줄 수 있기 때문에 통제대상이 되는 변수이다":"통제변수는 결과를 왜곡할 수 있어서 고정하거나 따로 처리해 영향을 없앱니다.","독립변수의 영향을 받아 종속변수에 영향을 미치는 변수이다":"매개변수는 독립변수가 종속변수에 이르는 중간 경로를 맡아 둘 사이를 이어 줍니다.","되풀이 되는 조사 과정을 통해 합의를 도출한다":"설문 결과를 피드백하며 여러 차례 다시 묻는 동안 의견이 한곳으로 모입니다.","두 변수 모두의 원인이 되는 제3의 변수로 설명되어서는 안된다":"인과관계가 성립하려면 두 변수의 관계가 다른 변수가 둘을 함께 움직인 허위관계가 아니어야 합니다.","모두 자료를 해석하고 구조화하는데 연구자의 객관성 유지가 필요하다":"자료를 풀이하고 정리하는 사람이 연구자이므로 어느 방법이든 주관을 개입시키지 않으려 노력해야 합니다.","모수와 통계치의 구분은 필요하지 않다":"전수 연구는 조사 값이 곧 모집단의 값이라서 표본값으로 모수를 추정할 일이 없습니다.","모집단이 큰 경우에는 표본 연구가 적합하다":"모집단이 크면 모두 조사하기 어려워 일부를 뽑아 추정하는 편이 현실적입니다.","목표달성에 대한 해석이 다양한 이해관계에 영향을 받을 수 있다":"관계자마다 이익이 달라 같은 성과를 성공으로도 실패로도 읽을 수 있습니다.","문제해결을 위한 사회복지 개입방법의 타당성을 검증할 수 있다":"조사로 어떤 개입이 정말 문제를 해결하는지 실제 근거로 따져 볼 수 있습니다.","반대 의견에 대한 패널 참가자들의 감정적 충돌을 줄일 수 있다":"서로 모르게 서면으로 응답하기 때문에 직접 부딪히는 대면 토론의 감정 다툼이 없습니다.","발견된 범주를 가지고 중심현상을 중심으로 인과적 조건을 만든다":"자료에서 찾은 범주들을 중심현상 둘레로 묶어 그 원인이 되는 조건을 정리합니다.","변화의 파동, 경향, 수준 등을 검토하여 개입의 효과성을 평가한다":"자료가 오르내리는 폭과 방향과 높이를 개입 전후로 비교해 효과를 판단합니다.","보고서의 형식은 의뢰기관의 요청에 따를 수 있다":"평가를 맡긴 기관이 원하는 양식과 내용 범위에 맞춰 보고서를 쓰는 경우가 있습니다.","보충적 자료 수집이 가능하다":"관찰은 면접으로 얻지 못한 행동 자료를 덧붙이는 보충 수단이 됩니다.","분석단위로는 기록단위와 맥락단위가 있다":"분석단위는 단어나 문장처럼 세는 기록단위와 그 의미를 정하는 앞뒤 범위인 맥락단위로 나뉩니다.","분석에 투입된 변수가 많아짐 (동일한 표집오차를 가정)":"같은 오차 수준을 유지하려면 분석 변수가 늘수록 표본이 더 커야 합니다.","비관여적 연구조사로 연구대상에게 영향을 미치지 않는다":"이미 만들어진 기록을 분석하므로 연구 과정이 대상의 반응을 바꾸지 않습니다.","비확률표집에 비해 정확한 표집틀이 필요하다":"확률표집은 모집단 요소의 명단이 있어야 무작위로 뽑을 수 있습니다.","사건이나 현상을 세분화하고 통계적 분석에 활용할 수 있는 정보를 제공한다":"현상을 나누어 수치로 바꾸면 통계 분석에 쓸 자료가 만들어집니다.","사전검사 결과 학교 부적응 학생들이":"선발 과정에서 집단이 이미 달라졌다는 사실을 사전검사로 알게 된 상황의 앞부분입니다.","사회변화와 임파워먼트에 초점을 둔다":"비판적 접근은 억압받는 집단이 힘을 얻고 사회를 바꾸도록 돕는 데 목적을 둡니다.","사회복지 서비스를 위한 지식과 기술을 제공할 수 있다":"조사 결과가 쌓이면 서비스 현장에서 쓸 지식과 기법의 바탕이 됩니다.","신뢰수준을 95%에서 99%로 높임 (다른 조건이 동일할 때)":"확신 수준을 높이면 더 넓은 범위를 확보해야 하므로 필요한 표본이 커집니다.","신뢰수준을 높이면 1종 오류는 줄어든다":"신뢰수준을 올리면 맞는 영가설을 잘못 기각할 위험인 유의수준이 낮아집니다.","신문 보도자료 속에 숨어있는 잠재적 내용도 분석에 포함될 수 있다":"내용분석은 드러난 표현뿐 아니라 글에 숨은 의미인 잠재적 내용도 대상으로 삼습니다.","실질적으로 측정하게 되는 연구개념의 세부적 속성이다":"조작적 정의로 정해진 것이 실제로 재는 대상, 곧 연구개념을 이루는 구체적 속성입니다.","실험집단과 통제집단의 사전 동질성 여부를 확인할 방법이 없다":"사전검사를 하지 않으므로 두 집단이 처음부터 비슷했는지 알 길이 없습니다.","실험집단과 통제집단의 참여자간":"두 집단 참여자가 서로 어울리는 상황을 말하며 다음 줄과 이어져 확산 문제를 설명합니다.","실험집단에 과도하게 모인 것이 확인되었다":"집단이 처음부터 다르게 구성된 선택의 편의로, 내적타당도를 해치는 요인입니다.","양적인 분석방법을 사용할 수 있다":"내용분석은 단어 빈도를 세는 식의 계량적 방법으로도 할 수 있습니다.","여러 대상이나 상황에 적용하여 개입의 효과를 측정한다":"여러 대상에 개입 시점을 달리해 변화가 개입 때문에 생겼는지를 확인합니다.","연구가설과 대조되는 가설이다":"영가설은 연구가설과 반대로 변수 사이에 차이나 관계가 없다는 쪽입니다.","연구가설에 대한 반증의 목적으로 설정된다":"가설은 맞음을 증명하기보다 틀린 증거를 찾는 방식으로 검증하므로 영가설을 먼저 세웁니다.","연구가설은 영가설을 통해 간접적으로 검증된다":"연구가설을 직접 입증하지 않고 영가설을 기각할 수 있는지로 판단합니다.","연구결과의 일반화를 위해 모집단의 속성이 반영된 충분한 표본을 조사하였다":"결과를 전체에 적용하려면 모집단의 특징을 닮은 표본을 충분한 크기로 뽑아야 합니다.","연구과정이 경직되지 않아 유연하게 진행된다":"질적연구는 처음 계획에 얽매이지 않고 자료를 모으며 방향을 바꿀 수 있습니다.","연구대상의 대표성이 낮은 경우 외적타당도를 저해할 수 있다":"뽑힌 대상이 모집단을 대표하지 못하면 결과를 다른 사람에게 일반화하기 어렵습니다.","연구의 개념적 틀 혹은 연구모형으로부터 도출될 수 있다":"연구가설은 연구자가 세운 개념 틀과 모형에서 이끌어 낸 예측입니다.","연구자 자신이 자료수집 도구가 된다":"질적 연구에서는 설문지 대신 연구자가 직접 보고 듣고 해석하며 자료를 모읍니다.","영가설을 기각하면 연구가설이 잠정적으로 채택된다":"영가설이 기각되면 연구가설을 받아들이지만 이후 연구에서 뒤집힐 수 있어 잠정적입니다.","영가설이 기각될 때 채택되는 가설이다":"대립가설은 영가설과 반대 주장이며 영가설이 기각될 때 받아들여집니다.","요인분석법은 타당도를 측정하는 방법이다":"문항들이 공통 요인으로 묶이는지 확인해 개념을 제대로 재는지 보는 구성 타당도 검증입니다.","유의확률(p)이 설정한 유의수준(α)보다 낮으면 영가설을 기각한다":"결과가 우연히 나올 확률이 허용 기준보다 작으면 영가설이 틀렸다고 보고 버립니다.","응답자의 이해능력과 응답능력을 고려하여야 한다":"응답자가 문장을 이해하고 답할 수 있어야 하므로 용어와 난이도를 대상에 맞춥니다.","의도적표집(purposive sampling)은 비확률표집이다":"연구자가 목적에 맞게 대상을 골라 뽑으므로 뽑힐 확률을 알 수 없는 비확률표집입니다.","이중(double-barreled)질문과 유도질문은 피하는 것이 좋다":"한 문항에 두 가지를 묻거나 답을 유도하면 응답자가 무엇에 답했는지 알 수 없게 됩니다.","일정한 규칙에 따라 측정대상의 속성에 수치를 부여하는 과정이다":"측정은 대상의 성질을 정해진 규칙으로 숫자나 기호로 나타내는 일입니다.","자료분석을 통하여 패턴과 의미를 모색한다":"질적연구는 숫자 대신 자료 속에 반복되는 양상을 찾고 그것이 뜻하는 바를 해석합니다.","자료에 근거하여 이론을 생성하는 연구도 가능하다":"근거이론은 기존 이론을 검증하는 대신 수집한 자료에서 새 이론을 만들어 냅니다.","전문가 패널을 대상으로 견해를 파악한다":"델파이기법은 해당 분야 전문가들에게 의견을 물어 모읍니다.","전수 연구에 비해 시간과 비용 측면에서 효율적이다":"모집단 전체 대신 일부만 조사하므로 들이는 시간과 비용이 적습니다.","조사 자료의 정리에 연구자의 편향이 발생할 수 있다":"자료를 분류하고 요약하는 단계에서 평가자의 선입견이 결과에 섞일 수 있습니다.","조작적 정의 · 개념적 정의와 실제 측정의 중간 과정에 해당한다":"조작화는 추상적인 개념 정의와 실제 측정 사이를 잇는 단계입니다.","조작적 정의를 통해 측정하고자 하는 개념의 주관적 해석의 수준을 낮춘다":"측정 방법을 구체적으로 정해 두면 사람마다 개념을 다르게 해석할 여지가 줄어듭니다.","질적 연구방법을 적용할 수 있다":"프로그램 평가에는 수치 대신 면접과 관찰로 참여자의 경험을 보는 방법도 쓸 수 있습니다.","질적조사에 비하여 양적조사의 표본크기가 상대적으로 크다":"통계적 일반화가 목적인 양적조사는 소수 사례를 깊이 보는 질적조사보다 표본이 큽니다.","참여자가 면접에 비협조적인 경우에도 활용가능하다":"관찰법은 말을 하지 않으려는 대상에게도 행동을 지켜보는 방식으로 자료를 얻을 수 있습니다.","측정을 위한 비관여적 관찰도 가능하다":"대상이 눈치채지 못하게 관찰해 반응성 없이 자료를 얻는 방법도 측정에 쓸 수 있습니다.","측정의 다각화를 통해 측정의 오류를 줄일 수 있다":"여러 방법으로 같은 대상을 재면 한 방법의 약점이 보완되어 오류가 줄어듭니다.","측정의 수준에 따라 명목, 서열, 등간, 비율의 4가지 유형으로 분류한다":"변수는 명목, 서열, 등간, 비율 네 수준으로 나뉘고 뒤로 갈수록 쓸 수 있는 연산이 많아집니다.","측정하려고 의도된 개념을 얼마나 정확하게 측정하는가를 나타내는 것이다":"타당도는 재려는 것을 제대로 재는지, 정확성의 정도를 말합니다.","쿤(T. Kuhn)은 당대의 지배적 패러다임에서 벗어나지 않는 것을 정상과학이라고 지칭하였다":"정상과학은 기존 패러다임을 받아들이고 그 틀 안에서 세부 문제를 푸는 연구를 말합니다.","클라이언트의 욕구를 파악하여 문제해결의 방향을 제시할 수 있다":"욕구조사를 하면 클라이언트에게 무엇이 필요한지 알아 해결할 방향을 잡을 수 있습니다.","통계치에 대한 확률(p)이 유의수준(α)보다 낮음":"검정 결과의 유의확률이 허용한 오류 기준보다 작으면 영가설을 기각하는 조건이 됩니다.","통제집단 사전사후검사 설계와 통제집단 사후검사 설계를 결합한 설계이다":"솔로몬 설계는 사전검사가 결과에 준 영향을 가르려고 두 설계를 합쳐 네 집단을 둡니다.","특성에 관하여 시간에 따른 변화를 분석할 수 있다":"코호트 연구는 같은 집단을 시간에 따라 따라가며 특성이 어떻게 달라지는지 봅니다.","판단의 합의를 얻기 위해서 극단적인 의견이 제외되는 문제가 있다":"합의를 향해 의견을 모으다 보면 소수의 극단적 견해가 버려진다는 한계가 있습니다.","포괄성과 상호배타성이 있도록 구성해야 한다":"응답항목은 가능한 답을 빠짐없이 담고 한 응답이 두 항목에 걸치지 않게 짜야 합니다.","표본의 크기가 대규모일 가능성이 높다":"양적연구는 통계로 일반화하기 위해 많은 사례를 조사하는 경우가 많습니다.","표본의 크기가 커지면 표집오차(sampling error)는 감소한다":"표본이 모집단에 가까워질수록 표본값과 참값의 차이가 작아집니다.","프로그램 내용에 대해 소통하면서":"통제집단이 프로그램 내용을 전해 듣고 따라 하면 효과 차이가 줄어드는 확산 문제가 생깁니다.","프로그램의 실행과정도 평가할 수 있다":"결과만이 아니라 계획대로 운영되었는지도 평가 대상이 되는데 이를 과정평가라고 합니다.","프로그램의 지속여부를 결정하는 객관적 근거를 제공할 수 있다":"프로그램을 이어 갈지는 평가 자료의 성과 수치 같은 객관적 증거로 판단할 수 있습니다.","프로그램 진행과정에서 일부 대상자가 참여를 중단하였다":"중도 탈락이 한쪽 집단에 몰리면 남은 사람만 비교되어 결과가 왜곡되는 실험 중도탈락입니다."}});if(window.DIAGRAM&&DIAGRAM.tnFlush)DIAGRAM.tnFlush();
/*tnote-data-end*/
